const treeById = new Map(TALENT_TREES.map((tree) => [tree.id, tree]));
// InterfaceTalents marks price-4 paliers with the demo lock icon.
export const DEMO_LOCKED_TALENT_TIER = 3;
const pair = (index) => ({ 1: 2, 2: 1, 4: 5, 5: 4 })[index];
const whole = (value) =>
  Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
function legacySpent(profile) {
  return Object.values(profile?.talents || {}).reduce(
    (sum, value) => sum + whole(value),
    0,
  );
}
export function talentSpent(build) {
  return TALENT_TREES.reduce((sum, tree) => {
    const owned = new Set(
      Array.isArray(build?.[tree.id]) ? build[tree.id] : [],
    );
    // Both branches of a pair share one purchase even in malformed input.
    return (
      sum +
      (owned.has(0) ? 1 : 0) +
      (owned.has(1) || owned.has(2) ? 2 : 0) +
      (owned.has(3) ? 3 : 0) +
      (owned.has(4) || owned.has(5) ? 4 : 0)
    );
  }, 0);
}
export function normalizeTalentBuild(input, budget = Infinity) {
  const result = {};
  let remaining = budget === Infinity ? Infinity : whole(budget);
  for (const tree of TALENT_TREES) {
    const raw = Array.isArray(input?.[tree.id]) ? input[tree.id] : [];
    const requested = new Set(
      raw.filter((index) => Number.isInteger(index) && index >= 0 && index < 6),
    );
    const owned = [];
    for (let index = 0; index < 6; index++) {
      const node = tree.nodes[index];
      if (!requested.has(index) || owned.includes(pair(index))) continue;
      if (
        node.requires.length &&
        !node.requires.some((required) => owned.includes(required))
      )
        continue;
      if (node.cost > remaining) continue;
      owned.push(index);
      remaining -= node.cost;
    }
    if (owned.length) result[tree.id] = owned;
  }
  return result;
}
export function canLearnTalent(profile, treeId, index) {
  const node = treeById.get(treeId)?.nodes[index];
  if (!Number.isInteger(index) || !node)
    return { allowed: false, reason: "Talento desconocido", cost: 0 };
  const build = normalizeTalentBuild(profile?.talentBuild);
  const owned = build[treeId] || [];
  if (owned.includes(index))
    return { allowed: false, reason: "Ya adquirido", cost: 0 };
  if (node.tier === DEMO_LOCKED_TALENT_TIER)
    return {
      allowed: false,
      reason: "No disponible en esta demo",
      cost: node.cost,
    };
  if (
    node.requires.length &&
    !node.requires.some((required) => owned.includes(required))
  )
    return {
      allowed: false,
      reason: "Requiere el nivel anterior del árbol",
      cost: node.cost,
    };
  const cost = owned.includes(pair(index)) ? 0 : node.cost;
  const available =
    whole(profile?.level) - legacySpent(profile) - talentSpent(build);
  if (cost > Math.max(0, available))
    return { allowed: false, reason: "Faltan puntos de talento", cost };
  return {
    allowed: true,
    reason: cost === 0 ? "Cambiar especialización gratis" : "Aprender talento",
    cost,
  };
}
export function learnTalent(profile, treeId, index) {
  const result = canLearnTalent(profile, treeId, index);
  if (!result.allowed) return result;
  const build = normalizeTalentBuild(profile.talentBuild);
  build[treeId] = [
    ...(build[treeId] || []).filter((value) => value !== pair(index)),
    index,
  ].sort((a, b) => a - b);
  profile.talentBuild = build;
  return result;
}
export function talentBonus(profile, effect) {
  const build = normalizeTalentBuild(
    profile?.talentBuild,
    Math.max(0, whole(profile?.level) - legacySpent(profile)),
  );
  return TALENT_TREES.reduce(
    (sum, tree) =>
      sum +
      (build[tree.id] || []).reduce((total, index) => {
        const node = tree.nodes[index];
        return total + (node.effect === effect ? node.amount : 0);
      }, 0),
    0,
  );
}
